'use strict';
(()=>{const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let DB,lang=document.documentElement.lang,profile={},notes={},storageOK=true;const key='editionskompass-slice-0.1';let showing=false;
function read(){try{const s=JSON.parse(sessionStorage.getItem(key)||'{}');if(s&&s.version==='0.1'){profile=s.profile||{};notes=s.notes||{}}}catch{storageOK=false}}
function save(){try{sessionStorage.setItem(key,JSON.stringify({version:'0.1',profile,notes}))}catch{storageOK=false;const n=$('#storage-note');if(n)n.textContent=DB.profile[lang].memoryFallback}}
function finding(k){const f=DB.findings[k],x=f[lang],de=lang==='de';$('#finding-output').innerHTML='<h3>'+E(x[0])+'</h3><pre><code>'+E(f.code)+'</code></pre><p><strong>'+(de?'Befund':'Finding')+':</strong> '+E(x[1])+'</p><p><strong>'+(de?'Mögliche Erklärung':'Possible explanation')+':</strong> '+E(x[2])+'</p><p><strong>'+(de?'Offene Frage':'Open question')+':</strong> '+E(x[3])+'</p>';$$('[data-finding]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.finding===k)))}
function label(id,value){const field=DB.profile[lang].fields.find(f=>f[0]===id);return field?.[2].find(o=>o[0]===value)?.[1]||DB.profile[lang].unknown}
function complete(){return DB.profile[lang].fields.every(([id])=>!!profile[id])}
function chosen(){if(profile.team==='solo')return 'anna';if(profile.team!=='team')return null;if(profile.horizon==='long')return 'albrecht';if(profile.output==='data')return 'korpus';if(profile.horizon==='limited'&&['book','interface'].includes(profile.output))return 'stadt';return null}
function reasonFor(who){const p=DB.profile[lang];return who==='anna'?p.reasonSolo:who==='albrecht'?p.reasonTeam:who==='korpus'?(lang==='de'?'Sie planen Editionsdaten im Team. Das Korpusprojekt zeigt, wie ein gut nutzbares Publikationsrepositorium vorbereitet wird.':'You plan edition data as a team. The corpus project shows how to prepare a usable publication repository.'):who==='stadt'?(lang==='de'?'Sie planen im Team eine begrenzte Projektphase mit Buch oder Interface. Das Drittmittelprojekt zeigt die Abstimmung von Ergebnissen, Qualifikationsarbeiten und Weiterarbeit.':'You are planning a fixed project phase as a team, with a book or interface. The grant-funded project illustrates coordination of outputs, doctoral work and continuation.'):''}
function caseLink(who){return DB.routes[lang]['full_'+who]}
function caseName(who){return ({anna:lang==='de'?'Kleinprojekt':'Small project',albrecht:lang==='de'?'Langzeitedition':'Long-term edition',korpus:lang==='de'?'Publikationsrepositorium':'Publication repository',stadt:lang==='de'?'Drittmittelprojekt':'Grant-funded project'})[who]}
function result(){const p=DB.profile[lang],de=lang==='de',who=chosen();if(!complete()){$('#strategy-result').innerHTML='<p>'+E(p.empty)+'</p>';return}let reason=who?reasonFor(who):(de?'Einige Angaben sind noch offen. Vergleichen Sie die vier Projekttypen, bevor Sie einen Ausgangsfall festlegen.':'Some details are still unclear. Compare the four project types before choosing a starting case.');$('#strategy-result').innerHTML='<div class="result-card"><p class="eyebrow">'+(de?'Ein nachvollziehbarer Einstieg':'A reasoned starting point')+'</p><h2>'+E(p.result)+'</h2><h3>'+E(p.why)+'</h3><p>'+E(reason)+'</p><div class="actions">'+(who?'<a href="'+caseLink(who)+'">'+caseName(who)+' →</a>':['anna','albrecht','korpus','stadt'].map(k=>'<a href="'+caseLink(k)+'">'+caseName(k)+' →</a>').join(''))+'<a href="'+DB.routes[lang].emre+'">Emre →</a></div>'+(profile.support!=='available'?'<p>'+E(p.supportOpen)+'</p>':'')+(profile.goal==='proposal'?'<p>'+E(p.proposalNote)+'</p>':'')+'<details><summary>'+(de?'Welche Angaben tragen diesen Vorschlag?':'Which answers led to this suggestion?')+'</summary><ul>'+DB.profile[lang].fields.map(([id,title])=>'<li><strong>'+E(title)+'</strong> '+E(label(id,profile[id]))+'</li>').join('')+'</ul><p>'+(de?'Regelstand 0.1: Alleinarbeit führt zum Kleinprojekt; ein langes Teamvorhaben zur Langzeitedition. Bei anderen Teamvorhaben führen reine Editionsdaten zum Publikationsrepositorium, Buch oder Interface in begrenzter Laufzeit zum Drittmittelprojekt. Anlass und Support ergänzen Aufgaben. Ungeklärte Angaben bleiben sichtbar. Es wird kein Passungs- oder Risikoscore berechnet.':'Rule version 0.1: individual work leads to the small project; long-term teamwork to the long-term edition. Other team projects with data alone lead to the publication repository; a book or interface in a fixed phase leads to the grant-funded project. Purpose and support add tasks; unknowns stay visible. No matching or risk score is calculated.')+'</p></details></div>';showing=true;updateDraft()}
function activeNotes(){const p=DB.profile[lang];return {action:notes.action??p.defaultAction,owner:notes.owner??p.defaultOwner,check:notes.check??p.defaultCheck,status:notes.status||'open'}}
function draft(){const p=DB.profile[lang],n=activeNotes(),de=lang==='de';return '# '+p.result+'\n\nEditionskompass · 0.1 · 2026-10-27\n\n'+DB.profile[lang].fields.map(([id,title])=>'- '+title+': '+label(id,profile[id])).join('\n')+'\n\n## '+p.why+'\n\n'+(chosen()?reasonFor(chosen()):(de?'Offene Angaben klären und die vier Projekttypen vergleichen.':'Clarify open details and compare the four project types.'))+(profile.support!=='available'?'\n\n'+p.supportOpen:'')+(profile.goal==='proposal'?'\n\n'+p.proposalNote:'')+'\n\n## '+p.action+'\n\n'+n.action+'\n\n## '+p.owner+'\n\n'+n.owner+'\n\n## '+p.check+'\n\n'+n.check+'\n\n## '+p.status+'\n\n'+(p.statuses.find(x=>x[0]===n.status)?.[1]||n.status)+'\n\n'+(de?'Arbeitsentwurf auf Grundlage Ihrer Angaben; keine durchgeführte Repo-Prüfung.':'A working draft based on your answers; no repository inspection has taken place.')+'\n'}
function updateDraft(){if($('#draft-text'))$('#draft-text').textContent=draft()}
function download(text,name,type){const blob=new Blob([text],{type});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function init(){DB=await(await fetch('/assets/data.json')).json();read();if($('#finding-output')){finding('import');$$('[data-finding]').forEach(b=>b.onclick=()=>finding(b.dataset.finding))}
const firstAnswers=new Map();
$$('[data-answer]').forEach(b=>b.onclick=()=>{const q=DB.quiz[lang].find(x=>x.id===b.dataset.quiz),index=+b.dataset.answer,correct=index===q.correct,first=!firstAnswers.has(q.id),de=lang==='de';if(first)firstAnswers.set(q.id,correct);$$('[data-quiz="'+q.id+'"]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#feedback-'+q.id).innerHTML='<strong>'+E(correct?(first?(de?'Volltreffer! +1 Punkt':'Bullseye! +1 point'):(de?'Richtig erkannt!':'You’ve got it!')):(de?'Knifflig! Hier steckt der kleine Haken:':'Tricky! Here’s the catch:'))+'</strong><p>'+E(q.feedback[index])+'</p><p>'+E(q.takeaway)+'</p>'+(!first?'<p class="small">'+(de?'Für den Punktestand zählt die erste Antwort. Weitere Antworten können Sie weiter ausprobieren.':'Your first answer counts towards the score. Feel free to try the other answers, too.')+'</p>':'');const score=[...firstAnswers.values()].filter(Boolean).length,total=DB.quiz[lang].length;$('#sample-score').textContent=(de?score+' / '+total+' Punkte · '+firstAnswers.size+' von '+total+' Fragen beantwortet':score+' / '+total+' points · '+firstAnswers.size+' of '+total+' questions answered')+(firstAnswers.size===total?(score===total?(de?' · Beide geknackt! Lust auf die nächste Runde?':' · Both cracked! Ready for another round?'):(de?' · Aufgelöst! Jetzt kennen Sie die Kniffe.':' · Answers revealed! Now you know the tricks.')):'')});
if($('#profile-form')){const p=DB.profile[lang];for(const [id] of p.fields)$('#'+id).value=profile[id]||'';const n=activeNotes();for(const id of ['action','owner','check'])$('#'+id).value=n[id];$('#action-status').value=n.status;if(!storageOK)$('#storage-note').textContent=p.memoryFallback;$('#profile-form').onchange=()=>{for(const [id] of p.fields)profile[id]=$('#'+id).value;save();if(showing)result();updateDraft()};$('#profile-form').onsubmit=e=>{e.preventDefault();result()};$('#action-form').oninput=()=>{notes={action:$('#action').value,owner:$('#owner').value,check:$('#check').value,status:$('#action-status').value};save();updateDraft()};$('#clear-profile').onclick=()=>{profile={};notes={};try{sessionStorage.removeItem(key)}catch{}$('#profile-form').reset();for(const id of ['action','owner','check'])$('#'+id).value='';$('#action-status').value='open';showing=false;$('#strategy-result').innerHTML='<p>'+E(p.empty)+'</p>';$('#draft-status').textContent=p.cleared;$('#draft-text').textContent=''};$('#download-draft').onclick=()=>{download(draft(),'editionskompass-entwurf-'+lang+'.md','text/markdown;charset=utf-8');$('#draft-status').textContent=p.exported};$('#download-profile').onclick=()=>{download(JSON.stringify({schema:'editionskompass-slice',version:'0.1',profile,notes:activeNotes()},null,2),'editionskompass-profil.json','application/json');$('#draft-status').textContent=p.exported};$('#print-draft').onclick=()=>{$('#print-draft-root').innerHTML='<h1>'+E(p.result)+'</h1><pre>'+E(draft().replace(/^# [^\n]*\n/,''))+'</pre>';document.body.classList.add('print-draft');window.print()};window.addEventListener('afterprint',()=>document.body.classList.remove('print-draft'));if(complete())result();updateDraft()}
if($('.search-form'))$('.search-form').onsubmit=e=>{e.preventDefault();const term=$('#site-search').value.trim().toLocaleLowerCase(lang);const hits=term?DB.search[lang].filter(x=>(x.title+' '+x.text).toLocaleLowerCase(lang).includes(term)):DB.search[lang];$('#search-results').innerHTML=hits.length?hits.map(x=>'<div class="search-result"><a href="'+x.url+'">'+E(x.title)+'</a><p>'+E(x.text)+'</p></div>').join(''):'<p>'+E(DB.ui[lang].nohits)+'</p>'};
if($('#material-type'))$('#material-type').onchange=()=>{$$('[data-material]').forEach(e=>e.hidden=$('#material-type').value!=='all'&&e.dataset.material!==$('#material-type').value)};$$('[data-print-page]').forEach(b=>b.onclick=()=>window.print());window.PORTAL={version:'0.1',draft,getProfile:()=>({...profile}),storageOK};}
init().catch(e=>{console.error(e);const box=$('#strategy-result');if(box)box.innerHTML='<p>'+(lang==='de'?'Die interaktive Hilfe konnte nicht geladen werden. Die HTML-Materialien bleiben verfügbar.':'The interactive helper could not be loaded. The HTML resources remain available.')+'</p>'});})();
